// 1. Creating a Buffer from a String
const myBuffer = Buffer.from("Hello World", "utf-8");

console.log("Raw Buffer (Hex):", myBuffer);
// Output: <Buffer 48 65 6c 6c 6f 20 57 6f 72 6c 64>

// 2. Converting back to a String
console.log("Decoded String:", myBuffer.toString());

// 3. Allocating a fixed-size empty Buffer (10 bytes)
const emptyBuf = Buffer.alloc(10);
emptyBuf.write("Node"); // Writes to the first 4 bytes
console.log("Allocated Buffer:", emptyBuf);

// 4. Checking length (in Bytes, NOT characters)
const emojiBuf = Buffer.from("🔥");
console.log("String length:", "🔥".length); // 2 (JS quirk)
console.log("Buffer byte length:", emojiBuf.length); // 4 (Emojis take 4 real bytes!)
